import json

# Fixed colour palette for ARC integer grids
ARC_PALETTE = {
    0: 'black', 1: 'blue', 2: 'red', 3: 'green', 4: 'yellow',
    5: 'light-gray', 6: 'magenta', 7: 'orange', 8: 'light-blue',
    9: 'maroon', 10: 'white', 11: 'dark-gray'
}

def _parse_arc_grid(obs: str):
    """Parse an ARC-style integer grid from the observation string."""
    # Find the marker line "<grid_0>" (or any <grid_k>)
    marker = None
    for line in obs.splitlines():
        if line.strip().startswith("<grid_"):
            marker = line.strip()
            break
    if marker is None:
        return None  # not ARC format

    # Rows start after the marker line
    lines = obs.splitlines()
    idx = lines.index(marker) + 1
    rows = []
    for i in range(idx, len(lines)):
        line = lines[i].strip()
        if not line.startswith('['):
            break  # end of grid rows
        try:
            row = json.loads(line)
            if not isinstance(row, list):
                break
            rows.append(row)
        except (json.JSONDecodeError, ValueError):
            break
    if not rows:
        return None
    return rows

def _parse_autumn_grid(obs: str):
    """Parse an Autumn-style JSON string grid from the observation string."""
    start = obs.find('[[', obs.find('Start of Direct Observation'))
    if start == -1:
        start = obs.find('[[')
    if start == -1:
        return None
    # Find the matching end of the outermost list
    # Scan for the last ']]' after the start
    depth = 0
    end = -1
    for i in range(start, len(obs)):
        if obs[i] == '[':
            depth += 1
        elif obs[i] == ']':
            depth -= 1
            if depth == 0:
                end = i + 1
                break
    if end == -1:
        # Fallback: assume it ends at last ']]' +2
        end = obs.rfind(']]') + 2
        if end < 2:
            return None
    try:
        grid = json.loads(obs[start:end])
        if not isinstance(grid, list) or not isinstance(grid[0], list):
            return None
        return grid
    except (json.JSONDecodeError, IndexError):
        return None

def _colour_name(value):
    """Convert an integer (ARC) or string (Autumn) to a standard name."""
    if isinstance(value, int):
        return ARC_PALETTE.get(value, f'unknown({value})')
    # Already a string (Autumn format)
    return value

def _summarise_grid(grid):
    """Return a concise description of non-background cells."""
    if not grid or not grid[0]:
        return "Grid: 0x0. Non-black cells: none"

    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0
    non_black = []
    for r in range(rows):
        for c in range(cols):
            cell = grid[r][c]
            # Determine if it's black background
            if isinstance(cell, int):
                is_bg = (cell == 0)
            else:  # string
                is_bg = (cell == 'black')
            if not is_bg:
                non_black.append((r, c, _colour_name(cell)))

    # Build summary
    summary = f"Grid: {rows}x{cols}."
    if not non_black:
        summary += " Non-black cells: none"
    else:
        # Keep under 2000 chars
        items = []
        for (r, c, col) in non_black:
            items.append(f"({r},{c}):{col}")
        cell_str = "; ".join(items)
        if len(cell_str) > 1900:  # leave room for rest
            # Truncate
            count = len(non_black)
            cell_str = "; ".join(items[:50])  # at most 50 cells
            if len(non_black) > 50:
                cell_str += f"; ... ({count - 50} more)"
        summary += f" Non-black cells: {cell_str}"
    return summary

def perceive(observation_history: list[str]) -> str:
    """
    Parse the current observation and return a concise text summary
    of decision-relevant features. Output is never empty and never raises.
    """
    try:
        obs = observation_history[-1]
    except IndexError:
        return "No observation"

    # Attempt to parse both formats
    grid = _parse_arc_grid(obs)
    if grid is None:
        grid = _parse_autumn_grid(obs)
    if grid is None:
        # Last resort: try to find any JSON array
        try:
            start = obs.find('[[', obs.find('Start of Direct Observation'))
            if start == -1:
                start = obs.find('[[')
            if start != -1:
                end = obs.rfind(']]') + 2
                if end > start:
                    grid = json.loads(obs[start:end])
        except (json.JSONDecodeError, IndexError):
            pass
    if grid is None or not grid:
        return "Grid: parse failed, no grid detected."

    return _summarise_grid(grid)

